import useImage from 'use-image'

/**
 * Target for floor plan image loading.
 * - `{ buildingId, floorNumber }` — load a specific building floor image
 * - `'campus'` — load the campus overhead image
 * - `undefined` (legacy) — load via thumbnail + full progressive path
 */
type FloorTarget = { buildingId: number; floorNumber: number } | 'campus'

/**
 * Progressive floor plan image loading with optional multi-floor target support.
 *
 * @param target - Optional target for the image to load:
 *   - `{ buildingId, floorNumber }`: loads `/api/floor-plan/{buildingId}/{floorNumber}`
 *   - `'campus'`: loads `/api/campus/image`
 *   - `undefined` (legacy): progressive thumbnail + full image for `/api/floor-plan/thumbnail` and `/api/floor-plan/image`
 *
 * All `useImage` hooks are called unconditionally (React rules of hooks).
 * Unused slots receive `''` (empty string) — `useImage('')` does not fetch.
 *
 * Returns shape unchanged: `{ image, isLoading, isFailed, isFullLoaded }`
 */
export function useFloorPlanImage(target?: FloorTarget) {
  // Multi-floor target URL (campus or specific floor)
  const targetUrl =
    target === 'campus'
      ? '/api/campus/image'
      : target
        ? `/api/floor-plan/${target.buildingId}/${target.floorNumber}`
        : ''

  // Legacy thumbnail URL — only used when target is undefined
  const thumbUrl = target ? '' : '/api/floor-plan/thumbnail'
  // Legacy full URL — only used when target is undefined
  const fullUrl = target ? '' : '/api/floor-plan/image'

  const [targetImg, targetStatus] = useImage(targetUrl)
  const [thumb, thumbStatus] = useImage(thumbUrl)
  const [full, fullStatus] = useImage(fullUrl)

  if (target) {
    // Multi-floor mode: single image, no progressive loading
    return {
      /** Single image for the specified floor or campus view */
      image: targetStatus === 'loaded' ? targetImg : undefined,
      /** True while the target image is loading */
      isLoading: targetStatus === 'loading',
      /** True if the target image failed to load */
      isFailed: targetStatus === 'failed',
      /** True once the target image has loaded */
      isFullLoaded: targetStatus === 'loaded',
    }
  }

  // Legacy mode: progressive thumbnail + full
  return {
    /** Best available image: full-res if loaded, else thumbnail, else undefined */
    image: fullStatus === 'loaded' ? full : thumbStatus === 'loaded' ? thumb : undefined,
    /** True while neither thumbnail nor full image has loaded yet */
    isLoading: thumbStatus === 'loading' && fullStatus !== 'loaded',
    /** True only when both thumbnail and full image failed to load */
    isFailed: thumbStatus === 'failed' && fullStatus === 'failed',
    /** True once the full-resolution image has loaded */
    isFullLoaded: fullStatus === 'loaded',
  }
}

import type { PathResult } from '@shared/pathfinding/types'
import type { NavFloor, NavNode } from '@shared/types'
import { useMemo } from 'react'

// ============================================================
// Types
// ============================================================

export type StepIcon =
  | 'straight'
  | 'turn-left'
  | 'turn-right'
  | 'sharp-left'
  | 'sharp-right'
  | 'arrive'
  | 'accessible'
  | 'stairs-up'
  | 'stairs-down'
  | 'elevator'
  | 'ramp'

export interface DirectionStep {
  /** Human-readable instruction, e.g. "Turn left at the cafeteria" */
  instruction: string
  icon: StepIcon
  /** Segment distance in normalized units (0–1 coordinate space) */
  distanceM: number
  /** Estimated seconds for this segment */
  durationSec: number
  /** True if this segment passes through a ramp or elevator node */
  isAccessibleSegment: boolean
  /** Floor ID where this instruction is presented */
  floorId: number
  /** Resolved floor number for display/grouping; falls back to floorId when metadata is missing */
  floorNumber: number
}

export interface DirectionsResult {
  steps: DirectionStep[]
  /** Sum of all segment distances in normalized units */
  totalDistanceNorm: number
  /** Sum of all step durations in seconds */
  totalDurationSec: number
}

// ============================================================
// Constants
// ============================================================

const WALKING_SPEED_STANDARD = 0.023 // normalized units/s
const WALKING_SPEED_ACCESSIBLE = 0.013 // normalized units/s

/** Node types that are visible/searchable destinations — eligible for landmark references */
const LANDMARK_TYPES = new Set(['room', 'landmark', 'entrance', 'elevator', 'restroom'])

// ============================================================
// Private helpers
// ============================================================

/**
 * Compute compass bearing in degrees (0–360) from point A to point B.
 * Uses screen-space convention: x increases right, y increases down.
 * atan2(dx, -dy) gives a bearing where 0°=north, 90°=east, 180°=south, 270°=west.
 */
function bearing(ax: number, ay: number, bx: number, by: number): number {
  const dx = bx - ax
  const dy = by - ay
  // atan2(x, -y) → clockwise from north in screen-space
  const rad = Math.atan2(dx, -dy)
  const deg = (rad * 180) / Math.PI
  return (deg + 360) % 360
}

/**
 * Normalize an angle difference to the range [-180, 180].
 */
function normalizeDelta(delta: number): number {
  let d = delta % 360
  if (d > 180) d -= 360
  if (d < -180) d += 360
  return d
}

/**
 * Euclidean distance between two normalized coordinate points.
 */
function euclideanDist(ax: number, ay: number, bx: number, by: number): number {
  const dx = bx - ax
  const dy = by - ay
  return Math.sqrt(dx * dx + dy * dy)
}

/**
 * Resolve a floor number from floor metadata, falling back to floorId when metadata is missing.
 */
function resolveFloorNumber(floorId: number, floorMap: Map<number, NavFloor>): number {
  return floorMap.get(floorId)?.floorNumber ?? floorId
}

/**
 * Determine vertical movement direction between two floors.
 * Uses resolved floor numbers first; if tied, falls back to floorId to keep output deterministic.
 */
function getVerticalDirection(
  fromFloorId: number,
  toFloorId: number,
  floorMap: Map<number, NavFloor>,
): 'up' | 'down' {
  const fromFloorNumber = resolveFloorNumber(fromFloorId, floorMap)
  const toFloorNumber = resolveFloorNumber(toFloorId, floorMap)

  if (toFloorNumber > fromFloorNumber) return 'up'
  if (toFloorNumber < fromFloorNumber) return 'down'

  return toFloorId >= fromFloorId ? 'up' : 'down'
}

/**
 * Classify bearing delta into a step icon.
 */
function classifyTurn(
  delta: number,
): Exclude<StepIcon, 'arrive' | 'accessible' | 'stairs-up' | 'stairs-down' | 'elevator' | 'ramp'> {
  const abs = Math.abs(delta)
  if (abs < 30) return 'straight'
  if (abs < 120) return delta > 0 ? 'turn-right' : 'turn-left'
  return delta > 0 ? 'sharp-right' : 'sharp-left'
}

/**
 * Build the instruction text for a direction step at the current (middle) node.
 * Appends " at the {label}" when the node is a searchable landmark-type.
 */
function buildInstruction(
  icon: Exclude<StepIcon, 'accessible' | 'stairs-up' | 'stairs-down' | 'elevator' | 'ramp'>,
  node: NavNode,
): string {
  const base: Record<
    Exclude<StepIcon, 'accessible' | 'stairs-up' | 'stairs-down' | 'elevator' | 'ramp'>,
    string
  > = {
    straight: 'Continue straight',
    'turn-left': 'Turn left',
    'turn-right': 'Turn right',
    'sharp-left': 'Sharp left',
    'sharp-right': 'Sharp right',
    arrive: `Arrive at ${node.label}`,
  }

  const text = base[icon]

  // For non-arrive steps: append landmark reference if the node is a visible, searchable destination
  if (icon !== 'arrive' && LANDMARK_TYPES.has(node.type) && node.searchable) {
    return `${text} at the ${node.label}`
  }

  return text
}

// ============================================================
// Core function
// ============================================================

/**
 * Convert an ordered list of node IDs into turn-by-turn walking directions.
 *
 * Algorithm:
 * - 0 or 1 nodes → empty result
 * - 2 nodes → single "arrive" step (no turn to compute)
 * - N nodes → for each triple (prev, curr, next): classify bearing delta → build step
 *             then append final "arrive" step for the last node
 */
export function generateDirections(
  nodeIds: string[],
  nodeMap: Map<string, NavNode>,
  mode: 'standard' | 'accessible',
  floorMap: Map<number, NavFloor> = new Map(),
): DirectionsResult {
  if (nodeIds.length < 2) {
    return { steps: [], totalDistanceNorm: 0, totalDurationSec: 0 }
  }

  const speed = mode === 'accessible' ? WALKING_SPEED_ACCESSIBLE : WALKING_SPEED_STANDARD
  const steps: DirectionStep[] = []
  let totalDistanceNorm = 0

  // Process intermediate nodes (all except the first and last)
  for (let i = 1; i < nodeIds.length - 1; i++) {
    // noUncheckedIndexedAccess: bounds are guaranteed by the for-loop condition
    const prevId = nodeIds[i - 1] as string
    const currId = nodeIds[i] as string
    const nextId = nodeIds[i + 1] as string

    // Nodes are guaranteed to be in the map when the caller provides valid IDs
    const prev = nodeMap.get(prevId)
    const curr = nodeMap.get(currId)
    const next = nodeMap.get(nextId)
    if (prev === undefined || curr === undefined || next === undefined) continue

    const distanceM = euclideanDist(prev.x, prev.y, curr.x, curr.y)
    const durationSec = distanceM / speed
    const currFloorNumber = resolveFloorNumber(curr.floorId, floorMap)
    const nextFloorNumber = resolveFloorNumber(next.floorId, floorMap)

    // Floor-change detection: check if curr→next crosses a floor boundary
    if (curr.floorId !== next.floorId) {
      const verticalDirection = getVerticalDirection(curr.floorId, next.floorId, floorMap)

      // Determine direction icon based on connector type and vertical direction
      let icon: StepIcon
      if (curr.type === 'stairs') {
        icon = verticalDirection === 'up' ? 'stairs-up' : 'stairs-down'
      } else if (curr.type === 'elevator') {
        icon = 'elevator'
      } else if (curr.type === 'ramp') {
        icon = 'ramp'
      } else {
        // Fallback: should not occur in a well-formed graph
        icon = verticalDirection === 'up' ? 'stairs-up' : 'stairs-down'
      }

      // Determine connector type name for instruction text
      const connectorTypeName =
        curr.type === 'elevator' ? 'elevator' : curr.type === 'ramp' ? 'ramp' : 'stairs'

      const instruction = `Take the ${connectorTypeName} ${verticalDirection} to Floor ${nextFloorNumber}`
      const isAccessibleSegment = curr.type === 'elevator' || curr.type === 'ramp'

      steps.push({
        instruction,
        icon,
        distanceM,
        durationSec,
        isAccessibleSegment,
        floorId: curr.floorId,
        floorNumber: currFloorNumber,
      })
      totalDistanceNorm += distanceM
      continue
    }

    const inBearing = bearing(prev.x, prev.y, curr.x, curr.y)
    const outBearing = bearing(curr.x, curr.y, next.x, next.y)
    const delta = normalizeDelta(outBearing - inBearing)

    const icon = classifyTurn(delta)
    const instruction = buildInstruction(icon, curr)
    const isAccessibleSegment = curr.type === 'ramp' || curr.type === 'elevator'

    steps.push({
      instruction,
      icon,
      distanceM,
      durationSec,
      isAccessibleSegment,
      floorId: curr.floorId,
      floorNumber: currFloorNumber,
    })
    totalDistanceNorm += distanceM
  }

  // Final "arrive" step — distance from second-to-last to last node
  const lastPrevId = nodeIds[nodeIds.length - 2] as string
  const lastId = nodeIds[nodeIds.length - 1] as string
  const lastPrev = nodeMap.get(lastPrevId)
  const last = nodeMap.get(lastId)
  if (lastPrev === undefined || last === undefined) {
    return { steps: [], totalDistanceNorm: 0, totalDurationSec: 0 }
  }

  const arriveDistance = euclideanDist(lastPrev.x, lastPrev.y, last.x, last.y)
  const arriveDuration = arriveDistance / speed
  const arriveInstruction = buildInstruction('arrive', last)

  steps.push({
    instruction: arriveInstruction,
    icon: 'arrive',
    distanceM: arriveDistance,
    durationSec: arriveDuration,
    isAccessibleSegment: last.type === 'ramp' || last.type === 'elevator',
    floorId: last.floorId,
    floorNumber: resolveFloorNumber(last.floorId, floorMap),
  })

  totalDistanceNorm += arriveDistance
  const totalDurationSec = steps.reduce((sum, s) => sum + s.durationSec, 0)

  return { steps, totalDistanceNorm, totalDurationSec }
}

// ============================================================
// routesAreIdentical utility
// ============================================================

/**
 * Returns true only if both routes were found and share the exact same ordered node IDs.
 */
export function routesAreIdentical(a: PathResult, b: PathResult): boolean {
  if (!a.found || !b.found) return false
  if (a.nodeIds.length !== b.nodeIds.length) return false
  return a.nodeIds.every((id, i) => id === b.nodeIds[i])
}

// ============================================================
// Hook
// ============================================================

/**
 * Memoized hook that converts a PathResult into turn-by-turn walking directions.
 *
 * Returns an empty result when:
 * - pathResult is null
 * - pathResult.found is false
 * - pathResult has fewer than 2 nodeIds
 */
export function useRouteDirections(
  pathResult: PathResult | null,
  nodeMap: Map<string, NavNode>,
  mode: 'standard' | 'accessible',
  floorMap?: Map<number, NavFloor>,
): DirectionsResult {
  return useMemo(() => {
    if (pathResult === null || !pathResult.found) {
      return { steps: [], totalDistanceNorm: 0, totalDurationSec: 0 }
    }
    return generateDirections(pathResult.nodeIds, nodeMap, mode, floorMap)
  }, [pathResult, nodeMap, mode, floorMap])
}

import { calculateWeight } from '@shared/pathfinding/graph-builder'
import type { NavEdge, NavFloorGpsBounds, NavNode } from '@shared/types'

/** Default confidence threshold for student-facing GPS rendering. */
export const DEFAULT_MAX_GPS_ACCURACY_METERS = 50

/**
 * Tiny tolerance used to make nearest-node tie handling deterministic.
 * Distances within this epsilon are treated as equivalent and resolved by node ID.
 */
const DISTANCE_TIE_EPSILON = 1e-9

/** Mean Earth radius in meters (IUGG). */
const EARTH_RADIUS_METERS = 6371008.8

export interface NormalizedPoint {
  /** Normalized X coordinate (0 = left edge, 1 = right edge). */
  x: number
  /** Normalized Y coordinate (0 = top edge, 1 = bottom edge). */
  y: number
}

export interface NearestWalkableNodeMatch {
  /** Selected nearest walkable node. */
  node: NavNode
  /** Euclidean distance in normalized map units. */
  distance: number
}

export interface SnapGpsToNodeResult extends NearestWalkableNodeMatch {
  /** Projected normalized point derived from the GPS fix. */
  projectedPoint: NormalizedPoint
}

/**
 * Returns true when floor bounds represent a valid rectangle in GPS space.
 */
export function isGpsBoundsCalibrated(
  bounds: NavFloorGpsBounds | null | undefined,
): bounds is NavFloorGpsBounds {
  if (bounds == null) return false

  return (
    isFiniteNumber(bounds.minLat)
    && isFiniteNumber(bounds.maxLat)
    && isFiniteNumber(bounds.minLng)
    && isFiniteNumber(bounds.maxLng)
    && bounds.minLat < bounds.maxLat
    && bounds.minLng < bounds.maxLng
  )
}

/**
 * Checks whether a latitude/longitude pair is inside configured floor GPS bounds.
 * Bounds are inclusive on every edge.
 */
export function isLatLngWithinBounds(
  latitude: number,
  longitude: number,
  bounds: NavFloorGpsBounds | null | undefined,
): boolean {
  if (!isFiniteNumber(latitude) || !isFiniteNumber(longitude)) return false
  if (!isGpsBoundsCalibrated(bounds)) return false

  return (
    latitude >= bounds.minLat
    && latitude <= bounds.maxLat
    && longitude >= bounds.minLng
    && longitude <= bounds.maxLng
  )
}

/**
 * Projects a GPS coordinate to normalized floor-map coordinates.
 *
 * Projection details:
 * - X grows left → right as longitude grows minLng → maxLng.
 * - Y grows top → bottom, so latitude is inverted (maxLat maps to y=0).
 *
 * Returns null when bounds are missing/invalid or the coordinate is out of bounds.
 */
export function projectLatLngToNormalizedPoint(
  latitude: number,
  longitude: number,
  bounds: NavFloorGpsBounds | null | undefined,
): NormalizedPoint | null {
  if (!isGpsBoundsCalibrated(bounds)) return null
  if (!isLatLngWithinBounds(latitude, longitude, bounds)) return null

  const lngSpan = bounds.maxLng - bounds.minLng
  const latSpan = bounds.maxLat - bounds.minLat

  if (lngSpan <= 0 || latSpan <= 0) return null

  const x = (longitude - bounds.minLng) / lngSpan
  const y = (bounds.maxLat - latitude) / latSpan

  const projected = { x, y }
  return isNormalizedPointInBounds(projected) ? projected : null
}

/**
 * Confidence gate for GPS fixes.
 *
 * Returns true only when the reported accuracy is finite, non-negative, and no
 * worse than `maxAccuracyMeters` (default: 50m).
 */
export function isGpsFixConfident(
  accuracyMeters: number,
  maxAccuracyMeters = DEFAULT_MAX_GPS_ACCURACY_METERS,
): boolean {
  return (
    isFiniteNumber(accuracyMeters)
    && isFiniteNumber(maxAccuracyMeters)
    && accuracyMeters >= 0
    && maxAccuracyMeters >= 0
    && accuracyMeters <= maxAccuracyMeters
  )
}

/**
 * Converts geolocation accuracy in meters to a marker ring radius in map pixels.
 *
 * Uses calibrated floor GPS bounds to estimate horizontal/vertical meter scales,
 * converts both to pixels, and returns their mean so ring size remains stable
 * across non-square maps.
 */
export function accuracyMetersToMapPixelRadius(
  accuracyMeters: number,
  bounds: NavFloorGpsBounds | null | undefined,
  mapWidthPx: number,
  mapHeightPx: number,
): number {
  if (!isFiniteNumber(accuracyMeters) || accuracyMeters <= 0) return 0
  if (!isFiniteNumber(mapWidthPx) || mapWidthPx <= 0) return 0
  if (!isFiniteNumber(mapHeightPx) || mapHeightPx <= 0) return 0

  const floorScale = deriveFloorScaleMeters(bounds)
  if (floorScale == null) return 0

  const xPixels = (accuracyMeters / floorScale.widthMeters) * mapWidthPx
  const yPixels = (accuracyMeters / floorScale.heightMeters) * mapHeightPx

  if (!isFiniteNumber(xPixels) || !isFiniteNumber(yPixels)) return 0

  return (xPixels + yPixels) / 2
}

/**
 * Finds the nearest walkable node to a normalized point.
 *
 * Candidate nodes are constrained to IDs that participate in at least one
 * floor-scoped edge with a finite standard weight, which keeps snapping aligned
 * with graph connectivity.
 */
export function findNearestWalkableNode(
  point: NormalizedPoint,
  nodes: readonly NavNode[],
  edges: readonly NavEdge[],
): NearestWalkableNodeMatch | null {
  if (!isNormalizedPointInBounds(point)) return null

  const walkableNodeIds = deriveWalkableNodeIds(nodes, edges)
  if (walkableNodeIds.size === 0) return null

  let bestMatch: NearestWalkableNodeMatch | null = null

  for (const node of nodes) {
    if (!walkableNodeIds.has(node.id)) continue

    const distance = calculateWeight(point.x, point.y, node.x, node.y)

    if (bestMatch == null) {
      bestMatch = { node, distance }
      continue
    }

    if (distance < bestMatch.distance - DISTANCE_TIE_EPSILON) {
      bestMatch = { node, distance }
      continue
    }

    if (
      Math.abs(distance - bestMatch.distance) <= DISTANCE_TIE_EPSILON
      && node.id.localeCompare(bestMatch.node.id) < 0
    ) {
      bestMatch = { node, distance }
    }
  }

  return bestMatch
}

/**
 * Convenience helper: projects GPS to normalized map space and snaps it to the
 * nearest walkable node on the floor.
 */
export function snapLatLngToNearestWalkableNode(
  latitude: number,
  longitude: number,
  bounds: NavFloorGpsBounds | null | undefined,
  nodes: readonly NavNode[],
  edges: readonly NavEdge[],
): SnapGpsToNodeResult | null {
  const projectedPoint = projectLatLngToNormalizedPoint(latitude, longitude, bounds)
  if (projectedPoint == null) return null

  const nearest = findNearestWalkableNode(projectedPoint, nodes, edges)
  if (nearest == null) return null

  return {
    ...nearest,
    projectedPoint,
  }
}

/**
 * Determines whether a normalized point is inside map bounds [0,1] x [0,1].
 */
export function isNormalizedPointInBounds(point: NormalizedPoint): boolean {
  return (
    isFiniteNumber(point.x)
    && isFiniteNumber(point.y)
    && point.x >= 0
    && point.x <= 1
    && point.y >= 0
    && point.y <= 1
  )
}

function deriveWalkableNodeIds(nodes: readonly NavNode[], edges: readonly NavEdge[]): Set<string> {
  const knownNodeIds = new Set(nodes.map((node) => node.id))
  const walkable = new Set<string>()

  for (const edge of edges) {
    if (!isFiniteNumber(edge.standardWeight)) continue

    if (knownNodeIds.has(edge.sourceId)) walkable.add(edge.sourceId)
    if (knownNodeIds.has(edge.targetId)) walkable.add(edge.targetId)
  }

  return walkable
}

function deriveFloorScaleMeters(
  bounds: NavFloorGpsBounds | null | undefined,
): { widthMeters: number; heightMeters: number } | null {
  if (!isGpsBoundsCalibrated(bounds)) return null

  const midLat = (bounds.minLat + bounds.maxLat) / 2
  const midLng = (bounds.minLng + bounds.maxLng) / 2

  const widthMeters = haversineDistanceMeters(midLat, bounds.minLng, midLat, bounds.maxLng)
  const heightMeters = haversineDistanceMeters(bounds.minLat, midLng, bounds.maxLat, midLng)

  if (!isFiniteNumber(widthMeters) || widthMeters <= 0) return null
  if (!isFiniteNumber(heightMeters) || heightMeters <= 0) return null

  return { widthMeters, heightMeters }
}

function haversineDistanceMeters(
  lat1: number,
  lng1: number,
  lat2: number,
  lng2: number,
): number {
  const lat1Rad = degreesToRadians(lat1)
  const lat2Rad = degreesToRadians(lat2)
  const dLat = degreesToRadians(lat2 - lat1)
  const dLng = degreesToRadians(lng2 - lng1)

  const sinDLat = Math.sin(dLat / 2)
  const sinDLng = Math.sin(dLng / 2)

  const a =
    sinDLat * sinDLat
    + Math.cos(lat1Rad) * Math.cos(lat2Rad) * sinDLng * sinDLng

  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))
  return EARTH_RADIUS_METERS * c
}

function degreesToRadians(value: number): number {
  return (value * Math.PI) / 180
}

function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value)
}

/**
 * useMapViewport — gesture math unit tests
 *
 * Strategy: test pure gesture helpers with lightweight mock Konva.Stage-like
 * objects. This avoids canvas/runtime setup while still validating the exact
 * transform arithmetic used by touch interactions.
 *
 * Requirements covered:
 *   TOUCH-01: focal-point zoom stays at finger midpoint at all rotation angles
 *   TOUCH-02: two-finger rotation pivots around touch midpoint
 *   TOUCH-03: per-frame 2-degree rotation threshold eliminates micro-jitter
 *   TOUCH-04: angle wrap-around normalization prevents ±π spin jumps
 *   TOUCH-05: two-finger midpoint drag pans naturally on phones
 */

import Konva from 'konva'
import { describe, expect, it } from 'vitest'

// ---------------------------------------------------------------------------
// Gesture helper imports from production code
// ---------------------------------------------------------------------------

import {
  applyRotationThreshold,
  computePivotPosition,
  computeTwoTouchFrameTransform,
  normalizeAngleDiffDeg,
  toStageLocalFromScreen,
} from './useMapViewport'

// ---------------------------------------------------------------------------
// Tolerance for floating-point comparisons
// ---------------------------------------------------------------------------

const EPS = 1e-6

function approx(actual: number, expected: number, eps = EPS): boolean {
  return Math.abs(actual - expected) < eps
}

// ---------------------------------------------------------------------------
// MockStage factory
//
// Builds a plain object that mimics the Konva.Stage API surface used in the
// corrected handleTouchMove formula. The getAbsoluteTransform mock is built
// from a real Konva.Transform so the math is identical to what the real stage
// produces.
// ---------------------------------------------------------------------------

type MockStage = {
  x: () => number
  y: () => number
  scaleX: () => number
  scaleY: () => number
  rotation: () => number
  getAbsoluteTransform: () => {
    copy: () => {
      invert: () => { point: (p: { x: number; y: number }) => { x: number; y: number } }
    }
  }
  container: () => { getBoundingClientRect: () => { left: number; top: number } }
}

interface MockStageOpts {
  x?: number
  y?: number
  scale?: number
  /** rotation in degrees */
  rotationDeg?: number
  /** container top-left offset (default 0, 0) */
  containerLeft?: number
  containerTop?: number
}

function mockStage(opts: MockStageOpts = {}): MockStage {
  const sx = opts.x ?? 0
  const sy = opts.y ?? 0
  const scale = opts.scale ?? 1
  const rotDeg = opts.rotationDeg ?? 0
  const containerLeft = opts.containerLeft ?? 0
  const containerTop = opts.containerTop ?? 0

  // Build a real Konva.Transform that encodes translate + rotate + scale.
  // This is the same decomposition Konva.Stage uses internally for getAbsoluteTransform().
  // Order: translate → rotate → scale  (Konva applies transforms in this order)
  const t = new Konva.Transform()
  t.translate(sx, sy)
  t.rotate((rotDeg * Math.PI) / 180) // Konva.Transform.rotate() takes radians
  t.scale(scale, scale)

  return {
    x: () => sx,
    y: () => sy,
    scaleX: () => scale,
    scaleY: () => scale,
    rotation: () => rotDeg,
    getAbsoluteTransform: () => ({
      copy: () => ({
        invert: () => ({
          point: (p: { x: number; y: number }) => t.copy().invert().point(p),
        }),
      }),
    }),
    container: () => ({
      getBoundingClientRect: () => ({ left: containerLeft, top: containerTop }),
    }),
  }
}

// ---------------------------------------------------------------------------
// TOUCH-01: focal-point zoom stays at finger midpoint at all rotation angles
//
// Tests call toStageLocalFromScreen(stage, screenPoint). The helper must use
// Konva's inverse transform (NOT naive division) so it is correct at any
// rotation angle.
// ---------------------------------------------------------------------------

describe('TOUCH-01: focal-point zoom', () => {
  it('Test 1: At 0° rotation — toStageLocalFromScreen returns correct stage-local coords', () => {
    // Arrange: stage at (0,0), scale=1, no rotation
    const stage = mockStage({ x: 0, y: 0, scale: 1, rotationDeg: 0 })
    const screenPoint = { x: 200, y: 300 }

    // At 0° with stage at origin: stageLocal = (200, 300) because inverse transform = identity
    const stageLocal = toStageLocalFromScreen(
      stage as Parameters<typeof toStageLocalFromScreen>[0],
      screenPoint,
    )

    // Verify the result matches what the Konva inverse transform produces
    expect(approx(stageLocal.x, 200)).toBe(true)
    expect(approx(stageLocal.y, 300)).toBe(true)
  })

  it('Test 2: At 45° rotation — toStageLocalFromScreen uses inverse transform (NOT naive division)', () => {
    // Arrange: stage at (0,0), scale=1, rotated 45°
    const stage = mockStage({ x: 0, y: 0, scale: 1, rotationDeg: 45 })
    const screenPoint = { x: 100, y: 100 }

    // The CORRECT inverse-transform result for (100,100) at 45° rotation
    // At 45°, screen (100,100) maps to stage-local: rotate by -45°
    // stageLocal.x = 100*cos(-45°) - 100*sin(-45°) = 100*(√2/2) + 100*(√2/2) = 100√2 ≈ 141.42
    // stageLocal.y = 100*sin(-45°) + 100*cos(-45°) = -100*(√2/2) + 100*(√2/2) = 0
    const expectedStageLocalX = 100 * Math.SQRT2 // ≈ 141.42
    const expectedStageLocalY = 0

    const stageLocal = toStageLocalFromScreen(
      stage as Parameters<typeof toStageLocalFromScreen>[0],
      screenPoint,
    )

    // The naive buggy formula would give: (100 - 0) / 1 = 100, (100 - 0) / 1 = 100
    // The correct inverse-transform result must be different
    expect(approx(stageLocal.x, expectedStageLocalX, 1e-4)).toBe(true)
    expect(approx(stageLocal.y, expectedStageLocalY, 1e-4)).toBe(true)
  })

  it('Test 3: At 90° rotation — toStageLocalFromScreen correctly maps screen axes to rotated stage axes', () => {
    // Arrange: stage at (0,0), scale=1, rotated 90°
    const stage = mockStage({ x: 0, y: 0, scale: 1, rotationDeg: 90 })
    const screenPoint = { x: 150, y: 200 }

    // The CORRECT inverse-transform result for (150,200) at 90° rotation
    // At 90°, screen (150,200) maps to stage-local: rotate by -90°
    // stageLocal.x = 150*cos(-90°) - 200*sin(-90°) = 0 + 200 = 200
    // stageLocal.y = 150*sin(-90°) + 200*cos(-90°) = -150 + 0 = -150
    const expectedStageLocalX = 200
    const expectedStageLocalY = -150

    const stageLocal = toStageLocalFromScreen(
      stage as Parameters<typeof toStageLocalFromScreen>[0],
      screenPoint,
    )

    // The naive buggy formula gives: (150 - 0) / 1 = 150, (200 - 0) / 1 = 200 — WRONG
    expect(approx(stageLocal.x, expectedStageLocalX, 1e-4)).toBe(true)
    expect(approx(stageLocal.y, expectedStageLocalY, 1e-4)).toBe(true)
  })
})

// ---------------------------------------------------------------------------
// TOUCH-02: two-finger rotation pivots around touch midpoint
//
// Tests call computePivotPosition(stageLocal, screenCenter, newScale, newRotationDeg)
// to compute the stage position that keeps stageLocal fixed under screenCenter
// after applying newScale and newRotationDeg.
// ---------------------------------------------------------------------------

describe('TOUCH-02: rotation pivot at touch midpoint', () => {
  it('Test 4: At 0° rotation — apply 10° rotation, position recalculated so midpoint stays fixed', () => {
    // Arrange: stageLocal = (150, 200), screenCenter = (150, 200), newRotation = 10°
    // At 0° initial rotation with stage at origin: stageLocal = screenCenter = (150, 200)
    const stageLocal = { x: 150, y: 200 }
    const screenCenter = { x: 150, y: 200 }
    const newScale = 1
    const newRotationDeg = 10

    // It computes: rotate(newRotDeg) * scale(newScale) * stageLocal = projected
    //              newPos = screenCenter - projected
    const newPos = computePivotPosition(stageLocal, screenCenter, newScale, newRotationDeg)

    // Verify: forward-project stageLocal through new transform => should land at screenCenter
    const t = new Konva.Transform()
    t.translate(newPos.x, newPos.y)
    t.rotate((newRotationDeg * Math.PI) / 180)
    t.scale(newScale, newScale)
    const mapped = t.point(stageLocal)

    expect(approx(mapped.x, screenCenter.x)).toBe(true)
    expect(approx(mapped.y, screenCenter.y)).toBe(true)
  })

  it('Test 5: At 30° initial rotation — apply 5° additional rotation, midpoint still stationary', () => {
    // Arrange: stage at (50, 100), scale=1.5, already rotated 30°, pinch at screen (200, 250)
    const stage = mockStage({ x: 50, y: 100, scale: 1.5, rotationDeg: 30 })
    const screenCenter = { x: 200, y: 250 }
    const newScale = 1.5
    const newRotationDeg = 35 // 30° + 5° additional

    // Get stage-local using the CORRECT inverse transform (toStageLocalFromScreen)
    const stageLocal = toStageLocalFromScreen(
      stage as Parameters<typeof toStageLocalFromScreen>[0],
      screenCenter,
    )

    // Compute correcting position
    const newPos = computePivotPosition(stageLocal, screenCenter, newScale, newRotationDeg)

    // Verify: forward-project stageLocal through new transform => should land at screenCenter
    const t = new Konva.Transform()
    t.translate(newPos.x, newPos.y)
    t.rotate((newRotationDeg * Math.PI) / 180)
    t.scale(newScale, newScale)
    const mapped = t.point(stageLocal)

    expect(approx(mapped.x, screenCenter.x)).toBe(true)
    expect(approx(mapped.y, screenCenter.y)).toBe(true)
  })
})

// ---------------------------------------------------------------------------
// TOUCH-03: per-frame 2-degree rotation threshold
//
// Tests call applyRotationThreshold(angleDiffDeg). This function returns true
// if the angleDiff should be applied (> 2°), false if it should be discarded
// (<= 2°).
// ---------------------------------------------------------------------------

describe('TOUCH-03: rotation threshold', () => {
  it('Test 6: angleDiff of 1° — rotation NOT applied (|1| <= 2)', () => {
    // Threshold is STRICT greater-than: |angleDiff| > 2 degrees
    expect(applyRotationThreshold(1)).toBe(false)
  })

  it('Test 7: angleDiff of exactly 2° — rotation NOT applied (threshold is strict greater-than)', () => {
    // |2| > 2 is false — rotation is NOT applied at exactly 2°
    expect(applyRotationThreshold(2)).toBe(false)
  })

  it('Test 8: angleDiff of 2.1° — rotation IS applied (|2.1| > 2 is true)', () => {
    // |2.1| > 2 is true — rotation IS applied above threshold
    expect(applyRotationThreshold(2.1)).toBe(true)
  })
})

// ---------------------------------------------------------------------------
// TOUCH-04: angle wrap-around should not create 300°+ rotation jumps
// ---------------------------------------------------------------------------

describe('TOUCH-04: angle wrap-around handling', () => {
  it('Test 9: normalizeAngleDiffDeg maps ±358° to ±2° shortest-path deltas', () => {
    expect(approx(normalizeAngleDiffDeg(-358), 2)).toBe(true)
    expect(approx(normalizeAngleDiffDeg(358), -2)).toBe(true)
  })

  it('Test 10: crossing +179° to -179° keeps rotation stable (delta normalized to +2°)', () => {
    const stage = mockStage({ x: 0, y: 0, scale: 1, rotationDeg: 30 })

    const frame = computeTwoTouchFrameTransform({
      stage,
      previousDistance: 120,
      currentDistance: 120,
      previousCenterScreen: { x: 200, y: 220 },
      currentCenterScreen: { x: 200, y: 220 },
      previousAngleRad: (179 * Math.PI) / 180,
      currentAngleRad: (-179 * Math.PI) / 180,
    })

    // Normalized delta is exactly +2°, and threshold is strict (> 2), so no rotation update.
    expect(approx(frame.newRotationDeg, 30)).toBe(true)
  })

  it('Test 11: crossing +179° to -176° applies minimal +5° rotation, not a -355° jump', () => {
    const stage = mockStage({ x: 0, y: 0, scale: 1, rotationDeg: 30 })

    const frame = computeTwoTouchFrameTransform({
      stage,
      previousDistance: 120,
      currentDistance: 120,
      previousCenterScreen: { x: 200, y: 220 },
      currentCenterScreen: { x: 200, y: 220 },
      previousAngleRad: (179 * Math.PI) / 180,
      currentAngleRad: (-176 * Math.PI) / 180,
    })

    expect(approx(frame.newRotationDeg, 35)).toBe(true)
  })
})

// ---------------------------------------------------------------------------
// TOUCH-05: two-finger midpoint drag should pan map naturally on phones
//
// Google/Apple maps keep the previously grabbed midpoint anchored while the
// midpoint moves, so two-finger drag (without scale change) translates the map.
// ---------------------------------------------------------------------------

describe('TOUCH-05: two-finger midpoint drag', () => {
  it('Test 12: midpoint translation with constant distance pans by the midpoint delta', () => {
    const stage = mockStage({ x: 0, y: 0, scale: 1, rotationDeg: 0 })

    const previousCenterScreen = { x: 100, y: 120 }
    const currentCenterScreen = { x: 130, y: 160 }

    const frame = computeTwoTouchFrameTransform({
      stage,
      previousDistance: 80,
      currentDistance: 80,
      previousCenterScreen,
      currentCenterScreen,
      previousAngleRad: 0,
      currentAngleRad: 0,
    })

    expect(approx(frame.newScale, 1)).toBe(true)
    expect(approx(frame.newRotationDeg, 0)).toBe(true)
    expect(approx(frame.newPosition.x, 30)).toBe(true)
    expect(approx(frame.newPosition.y, 40)).toBe(true)
  })

  it('Test 13: keeps the prior midpoint anchor under the new midpoint during pinch+drag', () => {
    const stage = mockStage({
      x: 50,
      y: 100,
      scale: 1.5,
      rotationDeg: 30,
      containerLeft: 20,
      containerTop: 35,
    })

    const previousCenterScreen = { x: 240, y: 250 }
    const currentCenterScreen = { x: 280, y: 305 }

    const frame = computeTwoTouchFrameTransform({
      stage,
      previousDistance: 120,
      currentDistance: 150,
      previousCenterScreen,
      currentCenterScreen,
      previousAngleRad: 0,
      currentAngleRad: 0,
    })

    const stageLocalAnchor = toStageLocalFromScreen(
      stage as Parameters<typeof toStageLocalFromScreen>[0],
      previousCenterScreen,
    )

    const t = new Konva.Transform()
    t.translate(frame.newPosition.x, frame.newPosition.y)
    t.rotate((frame.newRotationDeg * Math.PI) / 180)
    t.scale(frame.newScale, frame.newScale)
    const mapped = t.point(stageLocalAnchor)

    // current midpoint in container-relative coordinates
    const expectedX = currentCenterScreen.x - 20
    const expectedY = currentCenterScreen.y - 35

    expect(approx(mapped.x, expectedX, 1e-4)).toBe(true)
    expect(approx(mapped.y, expectedY, 1e-4)).toBe(true)
  })
})

import type { NavNode } from '@shared/types'
import { useCallback, useMemo, useState } from 'react'

/* ──────────────── Types ──────────────── */

export interface RouteSelection {
  start: NavNode | null
  destination: NavNode | null
  activeField: 'start' | 'destination'
  bothSelected: boolean
  setStart: (node: NavNode | null) => void
  setDestination: (node: NavNode | null) => void
  setActiveField: (field: 'start' | 'destination') => void
  setFromTap: (node: NavNode) => void
  swap: () => void
  clearStart: () => void
  clearDestination: () => void
  clearAll: () => void
}

/* ──────────────── Hook ──────────────── */

/**
 * Manages route selection state — start (A) and destination (B) nodes.
 *
 * `setFromTap` assigns a tapped node to whichever field `activeField` points to,
 * auto-advancing to the other field afterward. If the tapped node is already the
 * OTHER field, it swaps them instead of duplicating.
 */
export function useRouteSelection(): RouteSelection {
  const [start, setStartState] = useState<NavNode | null>(null)
  const [destination, setDestinationState] = useState<NavNode | null>(null)
  const [activeField, setActiveField] = useState<'start' | 'destination'>('start')

  const setStart = useCallback((node: NavNode | null) => {
    setStartState(node)
    setActiveField('destination')
  }, [])

  const setDestination = useCallback((node: NavNode | null) => {
    setDestinationState(node)
    setActiveField('start')
  }, [])

  const setFromTap = useCallback(
    (node: NavNode) => {
      if (activeField === 'start') {
        // If tapped node is already the destination, swap
        if (destination?.id === node.id) {
          setDestinationState(start)
          setStartState(node)
          setActiveField('destination')
        } else {
          setStartState(node)
          setActiveField('destination')
        }
      } else {
        // activeField === 'destination'
        // If tapped node is already the start, swap
        if (start?.id === node.id) {
          setStartState(destination)
          setDestinationState(node)
          setActiveField('start')
        } else {
          setDestinationState(node)
          setActiveField('start')
        }
      }
    },
    [activeField, start, destination],
  )

  const swap = useCallback(() => {
    if (start === null && destination === null) return
    const prevStart = start
    const prevDest = destination
    setStartState(prevDest)
    setDestinationState(prevStart)
  }, [start, destination])

  const clearStart = useCallback(() => {
    setStartState(null)
    setActiveField('start')
  }, [])

  const clearDestination = useCallback(() => {
    setDestinationState(null)
    setActiveField('destination')
  }, [])

  const clearAll = useCallback(() => {
    setStartState(null)
    setDestinationState(null)
    setActiveField('start')
  }, [])

  const bothSelected = useMemo(() => start !== null && destination !== null, [start, destination])

  return {
    start,
    destination,
    activeField,
    bothSelected,
    setStart,
    setDestination,
    setActiveField,
    setFromTap,
    swap,
    clearStart,
    clearDestination,
    clearAll,
  }
}

import type { NavNode, NavNodeType } from '@shared/types'
import { useCallback, useEffect, useRef, useState } from 'react'
import type { StudentGpsState } from '../gps/studentGpsState'
import { useLocationSearch } from '../hooks/useLocationSearch'
import type { RouteSelection } from '../hooks/useRouteSelection'

/* ──────────────── Constants ──────────────── */

const TYPE_COLORS: Record<string, string> = {
  room: '#3b82f6',
  entrance: '#22c55e',
  elevator: '#a855f7',
  restroom: '#f59e0b',
  landmark: '#ef4444',
}

const TYPE_LABELS: Record<string, string> = {
  room: 'Room',
  entrance: 'Entrance',
  elevator: 'Elevator',
  restroom: 'Restroom',
  landmark: 'Landmark',
}

/** POI types available for nearest search */
const NEAREST_POI_TYPES: Array<{ type: NavNodeType; label: string }> = [
  { type: 'restroom', label: 'Nearest Restroom' },
  { type: 'elevator', label: 'Nearest Elevator' },
  { type: 'entrance', label: 'Nearest Entrance' },
]

/* ──────────────── Props ──────────────── */

interface SearchOverlayProps {
  selection: RouteSelection
  nodes: NavNode[]
  onRouteTrigger: () => void
  /** Optional geolocation-derived state for use-location action + fallback copy. */
  gpsState?: StudentGpsState | null
  /** Sets route start from nearest walkable node to current GPS fix. */
  onUseMyLocation?: () => void
  /** When true (sheet is open), compact strip collapses to a minimal pill */
  sheetOpen?: boolean
  /** Called when user taps the compact A→B strip to reopen the directions sheet */
  onOpenSheet?: () => void
  /** True when a route result is available (sheet can be reopened) */
  hasRoute?: boolean
}

/* ──────────────── Component ──────────────── */

/**
 * Search overlay — dual search bars, full-screen suggestions, compact strip.
 *
 * Rendered as an HTML overlay above the Konva canvas. Uses absolute/fixed
 * positioning with z-index to float above the map.
 */
export function SearchOverlay({
  selection,
  nodes,
  onRouteTrigger,
  gpsState,
  onUseMyLocation,
  sheetOpen = false,
  onOpenSheet,
  hasRoute = false,
}: SearchOverlayProps) {
  const { query, results, search, searchNearest, clearSearch } = useLocationSearch(nodes)
  const [focusedField, setFocusedField] = useState<'start' | 'destination' | null>(null)
  const [showSuggestions, setShowSuggestions] = useState(false)
  const [nearestResults, setNearestResults] = useState<NavNode[]>([])
  const inputRef = useRef<HTMLInputElement>(null)

  // Determine mode: compact when both are selected and not actively searching
  const isCompact = selection.bothSelected && focusedField === null

  // When both become selected, auto-trigger route
  const prevBothRef = useRef(selection.bothSelected)
  useEffect(() => {
    if (selection.bothSelected && !prevBothRef.current) {
      setFocusedField(null)
      setShowSuggestions(false)
      clearSearch()
      onRouteTrigger()
    }
    prevBothRef.current = selection.bothSelected
  }, [selection.bothSelected, onRouteTrigger, clearSearch])

  // Focus input when suggestions panel opens
  useEffect(() => {
    if (showSuggestions && inputRef.current) {
      inputRef.current.focus()
    }
  }, [showSuggestions])

  const handleInputFocus = useCallback(
    (field: 'start' | 'destination') => {
      setFocusedField(field)
      setShowSuggestions(true)
      setNearestResults([])
      selection.setActiveField(field)
      // Reset search when opening a field
      search('')
    },
    [selection, search],
  )

  const handleInputChange = useCallback(
    (value: string) => {
      search(value)
      setNearestResults([])
    },
    [search],
  )

  const handleSelectSuggestion = useCallback(
    (node: NavNode) => {
      if (focusedField === 'start') {
        selection.setStart(node)
      } else if (focusedField === 'destination') {
        selection.setDestination(node)
      }
      setShowSuggestions(false)
      setFocusedField(null)
      clearSearch()
      setNearestResults([])
    },
    [focusedField, selection, clearSearch],
  )

