/**
 * Generates a grid graph with cols×rows nodes and edges to adjacent nodes.
 * Each node connects to its right and bottom neighbor (bidirectional).
 * Returns a NavGraph in the multi-floor format (buildings → floors → nodes/edges).
 */
function generateGridGraph(cols: number, rows: number): NavGraph {
  const nodes: NavGraph['buildings'][number]['floors'][number]['nodes'] = []
  const edges: NavGraph['buildings'][number]['floors'][number]['edges'] = []
  let edgeId = 0

  for (let x = 0; x < cols; x++) {
    for (let y = 0; y < rows; y++) {
      nodes.push({
        id: `node-${x}-${y}`,
        x: x / (cols - 1),
        y: y / (rows - 1),
        label: `Node ${x},${y}`,
        type: 'hallway',
        searchable: false,
        floorId: 1,
      })
    }
  }

  for (let x = 0; x < cols; x++) {
    for (let y = 0; y < rows; y++) {
      // Right neighbor
      if (x + 1 < cols) {
        const dx = 1 / (cols - 1)
        edges.push({
          id: `e-${edgeId++}`,
          sourceId: `node-${x}-${y}`,
          targetId: `node-${x + 1}-${y}`,
          standardWeight: dx,
          accessibleWeight: dx,
          accessible: true,
          bidirectional: true,
        })
      }
      // Bottom neighbor
      if (y + 1 < rows) {
        const dy = 1 / (rows - 1)
        edges.push({
          id: `e-${edgeId++}`,
          sourceId: `node-${x}-${y}`,
          targetId: `node-${x}-${y + 1}`,
          standardWeight: dy,
          accessibleWeight: dy,
          accessible: true,
          bidirectional: true,
        })
      }
    }
  }

  return {
    buildings: [
      {
        id: 1,
        name: 'Grid Test Building',
        floors: [
          {
            id: 1,
            floorNumber: 1,
            imagePath: 'floor-plan.png',
            updatedAt: '2026-01-01T00:00:00Z',
            nodes,
            edges,
          },
        ],
      },
    ],
  }
}

import { DEFAULT_MAX_GPS_ACCURACY_METERS, isGpsFixConfident } from '@shared/gps'
import type { GeolocationStatus } from '../hooks/useGeolocation'

export type StudentGpsFallbackReason =
  | 'floor-not-calibrated'
  | 'geolocation-unsupported'
  | 'permission-denied'
  | 'position-unavailable'
  | 'locating'
  | 'low-confidence'
  | 'no-nearest-node'

export interface DeriveStudentGpsStateInput {
  hasFloorCalibration: boolean
  geolocationStatus: GeolocationStatus
  accuracyMeters: number | null
  nearestNodeId: string | null
  maxAccuracyMeters?: number
}

export interface StudentGpsState {
  canUseMyLocation: boolean
  fallbackReason: StudentGpsFallbackReason | null
  fallbackMessage: string | null
  nearestNodeId: string | null
}

function buildFallbackMessage(reason: StudentGpsFallbackReason, maxAccuracyMeters: number): string {
  switch (reason) {
    case 'floor-not-calibrated':
      return 'Location assist is unavailable on this floor. Choose a start point manually.'
    case 'geolocation-unsupported':
      return 'This browser does not support geolocation. Choose a start point manually.'
    case 'permission-denied':
      return 'Location permission is blocked. Enable it or choose a start point manually.'
    case 'position-unavailable':
      return 'We could not determine your location. Try again or choose a start point manually.'
    case 'locating':
      return 'Finding your location… You can still choose a start point manually.'
    case 'low-confidence':
      return `Location accuracy is currently above ${maxAccuracyMeters}m. Choose a start point manually.`
    case 'no-nearest-node':
      return 'No walkable path node was found near your location. Choose a start point manually.'
  }
}

function withFallback(
  reason: StudentGpsFallbackReason,
  nearestNodeId: string | null,
  maxAccuracyMeters: number,
): StudentGpsState {
  return {
    canUseMyLocation: false,
    fallbackReason: reason,
    fallbackMessage: buildFallbackMessage(reason, maxAccuracyMeters),
    nearestNodeId,
  }
}

export function deriveStudentGpsState({
  hasFloorCalibration,
  geolocationStatus,
  accuracyMeters,
  nearestNodeId,
  maxAccuracyMeters = DEFAULT_MAX_GPS_ACCURACY_METERS,
}: DeriveStudentGpsStateInput): StudentGpsState {
  if (!hasFloorCalibration) {
    return withFallback('floor-not-calibrated', nearestNodeId, maxAccuracyMeters)
  }

  if (geolocationStatus === 'unsupported') {
    return withFallback('geolocation-unsupported', nearestNodeId, maxAccuracyMeters)
  }

  if (geolocationStatus === 'permission-denied') {
    return withFallback('permission-denied', nearestNodeId, maxAccuracyMeters)
  }

  if (geolocationStatus === 'unavailable') {
    return withFallback('position-unavailable', nearestNodeId, maxAccuracyMeters)
  }

  if (geolocationStatus === 'watching') {
    return withFallback('locating', nearestNodeId, maxAccuracyMeters)
  }

  if (!isGpsFixConfident(accuracyMeters ?? Number.NaN, maxAccuracyMeters)) {
    return withFallback('low-confidence', nearestNodeId, maxAccuracyMeters)
  }

  if (nearestNodeId == null) {
    return withFallback('no-nearest-node', nearestNodeId, maxAccuracyMeters)
  }

  return {
    canUseMyLocation: true,
    fallbackReason: null,
    fallbackMessage: null,
    nearestNodeId,
  }
}

import { useEffect, useMemo, useState } from 'react'

export type GeolocationStatus =
  | 'unsupported'
  | 'watching'
  | 'ready'
  | 'permission-denied'
  | 'unavailable'

export interface GeolocationFix {
  latitude: number
  longitude: number
  accuracyMeters: number
  timestamp: number
}

export interface GeolocationSnapshot {
  status: GeolocationStatus
  fix: GeolocationFix | null
  accuracyMeters: number | null
}

export interface GeolocationPositionLike {
  coords: {
    latitude: number
    longitude: number
    accuracy: number
  }
  timestamp: number
}

export interface GeolocationErrorLike {
  code: number
}

export interface GeolocationAdapter {
  watchPosition: (
    success: (position: GeolocationPositionLike) => void,
    error?: (error: GeolocationErrorLike) => void,
    options?: PositionOptions,
  ) => number
  clearWatch: (watchId: number) => void
}

export interface GeolocationWatchSession {
  watchId: number | null
  stop: () => void
}

export interface UseGeolocationOptions {
  enabled?: boolean
  geolocation?: GeolocationAdapter | null
  watchOptions?: PositionOptions
}

interface StartGeolocationWatchOptions {
  geolocation: GeolocationAdapter | null
  watchOptions: PositionOptions
  onSnapshot: (snapshot: GeolocationSnapshot) => void
}

const GEOLOCATION_PERMISSION_DENIED_CODE = 1

const DEFAULT_WATCH_OPTIONS: PositionOptions = {
  enableHighAccuracy: true,
  maximumAge: 0,
  timeout: 10000,
}

const INACTIVE_GEOLOCATION_SNAPSHOT = createGeolocationSnapshot('unavailable')

export function createGeolocationSnapshot(
  status: GeolocationStatus,
  fix: GeolocationFix | null = null,
): GeolocationSnapshot {
  return {
    status,
    fix,
    accuracyMeters: fix?.accuracyMeters ?? null,
  }
}

export function mapGeolocationErrorCode(code: number): 'permission-denied' | 'unavailable' {
  return code === GEOLOCATION_PERMISSION_DENIED_CODE ? 'permission-denied' : 'unavailable'
}

export function startGeolocationWatch({
  geolocation,
  watchOptions,
  onSnapshot,
}: StartGeolocationWatchOptions): GeolocationWatchSession {
  if (geolocation == null) {
    onSnapshot(createGeolocationSnapshot('unsupported'))
    return {
      watchId: null,
      stop: () => {},
    }
  }

  let isActive = true

  const emitSnapshot = (snapshot: GeolocationSnapshot) => {
    if (!isActive) return
    onSnapshot(snapshot)
  }

  emitSnapshot(createGeolocationSnapshot('watching'))

  let watchId: number

  try {
    watchId = geolocation.watchPosition(
      (position) => {
        const fix = toGeolocationFix(position)
        if (fix == null) {
          emitSnapshot(createGeolocationSnapshot('unavailable'))
          return
        }
        emitSnapshot(createGeolocationSnapshot('ready', fix))
      },
      (error) => {
        emitSnapshot(createGeolocationSnapshot(mapGeolocationErrorCode(error.code)))
      },
      watchOptions,
    )
  } catch {
    emitSnapshot(createGeolocationSnapshot('unavailable'))
    return {
      watchId: null,
      stop: () => {
        isActive = false
      },
    }
  }

  return {
    watchId,
    stop: () => {
      if (!isActive) return
      isActive = false
      geolocation.clearWatch(watchId)
    },
  }
}

function toGeolocationFix(position: GeolocationPositionLike): GeolocationFix | null {
  const latitude = position.coords.latitude
  const longitude = position.coords.longitude
  const accuracyMeters = position.coords.accuracy
  const timestamp = position.timestamp

  if (!Number.isFinite(latitude)) return null
  if (!Number.isFinite(longitude)) return null
  if (!Number.isFinite(accuracyMeters) || accuracyMeters < 0) return null
  if (!Number.isFinite(timestamp)) return null

  return {
    latitude,
    longitude,
    accuracyMeters,
    timestamp,
  }
}

function resolveNavigatorGeolocation(): GeolocationAdapter | null {
  if (typeof navigator === 'undefined') return null
  if (navigator.geolocation == null) return null

  return {
    watchPosition: navigator.geolocation.watchPosition.bind(navigator.geolocation),
    clearWatch: navigator.geolocation.clearWatch.bind(navigator.geolocation),
  }
}

export function useGeolocation(options: UseGeolocationOptions = {}): GeolocationSnapshot {
  const enabled = options.enabled ?? true
  const geolocation = useMemo(
    () => options.geolocation ?? resolveNavigatorGeolocation(),
    [options.geolocation],
  )
  const watchOptions = options.watchOptions ?? DEFAULT_WATCH_OPTIONS

  const [snapshot, setSnapshot] = useState<GeolocationSnapshot>(() => {
    if (!enabled) return INACTIVE_GEOLOCATION_SNAPSHOT
    if (geolocation == null) return createGeolocationSnapshot('unsupported')
    return createGeolocationSnapshot('watching')
  })

  useEffect(() => {
    if (!enabled) {
      setSnapshot(INACTIVE_GEOLOCATION_SNAPSHOT)
      return
    }

    const session = startGeolocationWatch({
      geolocation,
      watchOptions,
      onSnapshot: setSnapshot,
    })

    return () => {
      session.stop()
    }
  }, [enabled, geolocation, watchOptions])

  return snapshot
}

import type { NavFloorGpsBounds } from '@shared/types'
import { eq } from 'drizzle-orm'
import { db } from './db/client'
import { floors } from './db/schema'

export interface FloorGpsBoundsColumns {
  gpsMinLat: number | null
  gpsMaxLat: number | null
  gpsMinLng: number | null
  gpsMaxLng: number | null
}

export type FloorGpsBoundsErrorCode =
  | 'INVALID_REQUEST'
  | 'GPS_BOUNDS_INCOMPLETE'
  | 'BOUNDS_RANGE_INVALID'
  | 'FLOOR_NOT_FOUND'

type FloorGpsBoundsErrorStatus = 400 | 404

const FLOOR_GPS_BOUNDS_ERROR_STATUS = {
  INVALID_REQUEST: 400,
  GPS_BOUNDS_INCOMPLETE: 400,
  BOUNDS_RANGE_INVALID: 400,
  FLOOR_NOT_FOUND: 404,
} as const satisfies Record<FloorGpsBoundsErrorCode, FloorGpsBoundsErrorStatus>

export class FloorGpsBoundsError extends Error {
  readonly code: FloorGpsBoundsErrorCode
  readonly status: FloorGpsBoundsErrorStatus

  constructor(code: FloorGpsBoundsErrorCode, message: string) {
    super(message)
    this.name = 'FloorGpsBoundsError'
    this.code = code
    this.status = FLOOR_GPS_BOUNDS_ERROR_STATUS[code]
  }
}

export interface FloorGpsBoundsUpdateResult {
  ok: true
  floorId: number
  gpsBounds: NavFloorGpsBounds | null
}

interface FloorGpsBoundsRow extends FloorGpsBoundsColumns {
  id: number
}

export interface FloorGpsBoundsStoreTx {
  getFloorById(floorId: number): Promise<FloorGpsBoundsRow | null>
  updateFloorGpsBounds(floorId: number, bounds: FloorGpsBoundsColumns): Promise<FloorGpsBoundsRow | null>
}

export interface FloorGpsBoundsStore {
  transaction<T>(callback: (tx: FloorGpsBoundsStoreTx) => Promise<T>): Promise<T>
}

type DrizzleFloorGpsBoundsTx = Pick<typeof db, 'select' | 'update'>

function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value)
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null
}

function parseFloorGpsBoundsTuple(values: {
  minLat: unknown
  maxLat: unknown
  minLng: unknown
  maxLng: unknown
}): FloorGpsBoundsColumns {
  const { minLat, maxLat, minLng, maxLng } = values
  const tupleValues = [minLat, maxLat, minLng, maxLng] as const

  if (tupleValues.some(value => value === undefined)) {
    throw new FloorGpsBoundsError(
      'GPS_BOUNDS_INCOMPLETE',
      'minLat, maxLat, minLng, and maxLng must all be provided',
    )
  }

  if (tupleValues.every(value => value === null)) {
    return {
      gpsMinLat: null,
      gpsMaxLat: null,
      gpsMinLng: null,
      gpsMaxLng: null,
    }
  }

  if (tupleValues.some(value => value === null)) {
    throw new FloorGpsBoundsError(
      'GPS_BOUNDS_INCOMPLETE',
      'GPS bounds must be a complete numeric tuple or a full null clear tuple',
    )
  }

  if (
    !isFiniteNumber(minLat)
    || !isFiniteNumber(maxLat)
    || !isFiniteNumber(minLng)
    || !isFiniteNumber(maxLng)
  ) {
    throw new FloorGpsBoundsError(
      'INVALID_REQUEST',
      'minLat, maxLat, minLng, and maxLng must be finite numbers or all null',
    )
  }

  if (minLat >= maxLat || minLng >= maxLng) {
    throw new FloorGpsBoundsError(
      'BOUNDS_RANGE_INVALID',
      'GPS bounds must satisfy minLat < maxLat and minLng < maxLng',
    )
  }

  return {
    gpsMinLat: minLat,
    gpsMaxLat: maxLat,
    gpsMinLng: minLng,
    gpsMaxLng: maxLng,
  }
}

/**
 * Converts nullable DB floor GPS columns into a complete GPS bounds object.
 * Returns null when any value is missing (or non-finite), ensuring callers never
 * serialize partial coordinate tuples.
 */
export function toNavFloorGpsBounds(row: FloorGpsBoundsColumns): NavFloorGpsBounds | null {
  if (
    !isFiniteNumber(row.gpsMinLat)
    || !isFiniteNumber(row.gpsMaxLat)
    || !isFiniteNumber(row.gpsMinLng)
    || !isFiniteNumber(row.gpsMaxLng)
  ) {
    return null
  }

  return {
    minLat: row.gpsMinLat,
    maxLat: row.gpsMaxLat,
    minLng: row.gpsMinLng,
    maxLng: row.gpsMaxLng,
  }
}

export function serializeFloorGpsBounds(row: FloorGpsBoundsColumns): { gpsBounds?: NavFloorGpsBounds } {
  const gpsBounds = toNavFloorGpsBounds(row)
  return gpsBounds ? { gpsBounds } : {}
}

export function parseFloorGpsBoundsUpdatePayload(payload: unknown): FloorGpsBoundsColumns {
  if (!isRecord(payload)) {
    throw new FloorGpsBoundsError('INVALID_REQUEST', 'Request body must be a JSON object')
  }

  return parseFloorGpsBoundsTuple({
    minLat: payload.minLat,
    maxLat: payload.maxLat,
    minLng: payload.minLng,
    maxLng: payload.maxLng,
  })
}

function createDrizzleStoreTx(tx: DrizzleFloorGpsBoundsTx): FloorGpsBoundsStoreTx {
  return {
    async getFloorById(floorId) {
      const [row] = await tx
        .select({
          id: floors.id,
          gpsMinLat: floors.gpsMinLat,
          gpsMaxLat: floors.gpsMaxLat,
          gpsMinLng: floors.gpsMinLng,
          gpsMaxLng: floors.gpsMaxLng,
        })
        .from(floors)
        .where(eq(floors.id, floorId))
        .limit(1)

      return row ?? null
    },

    async updateFloorGpsBounds(floorId, bounds) {
      const [row] = await tx
        .update(floors)
        .set({
          ...bounds,
          updatedAt: new Date().toISOString(),
        })
        .where(eq(floors.id, floorId))
        .returning({
          id: floors.id,
          gpsMinLat: floors.gpsMinLat,
          gpsMaxLat: floors.gpsMaxLat,
          gpsMinLng: floors.gpsMinLng,
          gpsMaxLng: floors.gpsMaxLng,
        })

      return row ?? null
    },
  }
}

const drizzleFloorGpsBoundsStore: FloorGpsBoundsStore = {
  transaction(callback) {
    return db.transaction(async (tx) => callback(createDrizzleStoreTx(tx)))
  },
}

async function executeUpdateFloorGpsBounds(
  tx: FloorGpsBoundsStoreTx,
  floorId: number,
  bounds: FloorGpsBoundsColumns,
): Promise<FloorGpsBoundsUpdateResult> {
  const existingFloor = await tx.getFloorById(floorId)
  if (!existingFloor) {
    throw new FloorGpsBoundsError('FLOOR_NOT_FOUND', `Floor ${floorId} was not found`)
  }

  const updatedFloor = await tx.updateFloorGpsBounds(existingFloor.id, bounds)
  if (!updatedFloor) {
    throw new FloorGpsBoundsError('FLOOR_NOT_FOUND', `Floor ${floorId} was not found`)
  }

  return {
    ok: true,
    floorId: updatedFloor.id,
    gpsBounds: toNavFloorGpsBounds(updatedFloor),
  }
}

export async function updateFloorGpsBounds(
  floorId: number,
  bounds: FloorGpsBoundsColumns,
  options?: { store?: FloorGpsBoundsStore },
): Promise<FloorGpsBoundsUpdateResult> {
  if (!Number.isInteger(floorId) || floorId <= 0) {
    throw new FloorGpsBoundsError('INVALID_REQUEST', 'floorId must be a positive integer')
  }

  const store = options?.store ?? drizzleFloorGpsBoundsStore
  return store.transaction(async (tx) => executeUpdateFloorGpsBounds(tx, floorId, bounds))
}

export async function updateFloorGpsBoundsFromPayload(
  floorId: number,
  payload: unknown,
  options?: { store?: FloorGpsBoundsStore },
): Promise<FloorGpsBoundsUpdateResult> {
  const bounds = parseFloorGpsBoundsUpdatePayload(payload)
  return updateFloorGpsBounds(floorId, bounds, options)
}

import { Navigate, Outlet } from 'react-router-dom'
import { useAuth } from '../hooks/useAuth'

export function ProtectedRoute() {
  const { authenticated, loading } = useAuth()

  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen">
        <span>Loading...</span>
      </div>
    )
  }

  if (!authenticated) {
    return <Navigate to="/admin/login" replace />
  }

  return <Outlet />
}
